<?php require_once __DIR__.'/../config/config.php'; if(!empty($_SESSION['admin_id'])){header('Location: '.url('admin/dashboard.php'));exit;} $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$s=db()->prepare("SELECT * FROM admins WHERE email=? AND status='active'");$s->execute([trim($_POST['email']??'')]);$a=$s->fetch();if($a&&password_verify($_POST['password']??'',$a['password_hash'])){session_regenerate_id(true);unset($_SESSION['user_id'],$_SESSION['user_name'],$_SESSION['user_role'],$_SESSION['user_email']);$_SESSION['admin_id']=$a['id'];$_SESSION['admin_name']=$a['name'];db()->prepare("UPDATE admins SET last_login=NOW() WHERE id=?")->execute([$a['id']]);header('Location: '.url('admin/dashboard.php'));exit;} $error='Invalid email or password.';} ?>
